import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/qr_g7_keks.B6q4c7CX.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as o,o as r,c as n,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"G7, ONE+","description":"","frontmatter":{"source_hash":"2d4887a3b0","source_commit":"baee8de","i18n_outdated":true},"headers":[],"relativePath":"fr/install/g7.md","filePath":"fr/install/g7.md"}'),p={name:"fr/install/g7.md"};function c(d,i,u,m,v,h){return r(),n("div",null,[...i[0]||(i[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Dex</p></div><h3 id="g7-or-one" tabindex="-1">G7 ou ONE+ <a class="header-anchor" href="#g7-or-one" aria-label="Permalink to &quot;G7 ou ONE+ {#g7-or-one}&quot;">​</a></h3><p>Cette page explique comment connecter directement un capteur Dexcom G7 ou ONE+ à xDrip. Le capteur et l&#39;émetteur forment une seule unité jetable et, du point de vue de xDrip, G7 et ONE+ sont le même appareil : toutes les étapes ci-dessous s&#39;appliquent aux deux.</p><p>Pour le G6 ou le Dexcom ONE, consultez plutôt la <a href="./g6.html">page G6, Dexcom ONE</a>.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Une partie de ces informations s&#39;applique aussi au Stelo connecté directement à xDrip : consultez le <a href="./datasource.html">guide des sources de données</a> pour connaître la prise en charge actuelle du Stelo.</p></div><h4 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h4><ul><li>Vérifiez que la configuration de votre téléphone correspond aux <a href="./prerequisites.html">prérequis</a> de xDrip (synchronisation de l&#39;heure, optimisation de la batterie).</li><li>Assurez-vous que xDrip est au moins à la version 2026.05.06.</li><li>Une seule application peut collecter les données du capteur : désinstallez l&#39;application Dexcom si xDrip doit être le collecteur. Si vous devez conserver l&#39;application Dexcom, elle seule peut collecter : utilisez alors xDrip en abonné <a href="./companion.html">application compagnon</a>. Il en va de même pour l&#39;application BYOD G7, qui ne peut pas diffuser directement vers xDrip.</li></ul><div class="info custom-block"><p class="custom-block-title">t:slim / l&#39;ordre du récepteur compte</p><p>Connectez xDrip <strong>en premier</strong>. Si une pompe ou un récepteur se connecte au capteur avant xDrip, xDrip ne pourra pas s&#39;y connecter : si l&#39;un d&#39;eux fonctionne déjà, désactivez-le et attendez 15 minutes.</p></div><div class="warning custom-block"><p class="custom-block-title">N&#39;appairez pas depuis les paramètres Bluetooth d&#39;Android</p><p>N&#39;appairez jamais le capteur depuis la page des paramètres Bluetooth d&#39;Android : laissez xDrip déclencher la demande d&#39;appairage et acceptez-la lorsqu&#39;elle vous est proposée.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurer xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurer xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Dex</p></div><p>Scannez ensuite ce QR code avec Paramètres → <a href="./../use/copysettings.html#auto-configure">Configuration automatique</a> et acceptez l&#39;importation. Il charge les données de prise en charge du G7 dont xDrip a besoin, qui ne peuvent pas être saisies manuellement. Cette configuration ne se fait qu&#39;une fois : inutile de la répéter à chaque nouveau capteur.</p><p>QR code - Cliquez sur l&#39;image pour l&#39;agrandir</p><p><a href="../../install/images/qr_g7_keks.png"><img src="'+t+'" style="zoom:50%;"></a></p><p>Vérifiez ensuite les paramètres ci-dessous : la plupart correspondent aux valeurs par défaut de xDrip, il s&#39;agit donc d&#39;une vérification plutôt que d&#39;une reconfiguration. Le rôle de chaque paramètre est décrit dans les pages <a href="./g6.html#dexcom-advanced-settings-reference">référence des paramètres avancés Dexcom</a>, <a href="./../use/bluetooth.html">Paramètres Bluetooth</a> et <a href="./../use/misc.html">Autres options diverses</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres de débogage Dexcom</p></div><div class="admonition xdripitem"><p class="admonition-title">Algorithme natif <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utiliser l&#39;algorithme interne de l&#39;émetteur pour calculer les valeurs de glycémie lorsque cela est possible.</p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrer le capteur <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Redémarrer automatiquement un capteur lorsqu&#39;il s&#39;arrête</p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrage préventif <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Redémarrer un capteur avant la fin de la session les jours 6/9 pour éviter le temps de préparation</p></div><p>Une session G7 ne peut jamais être redémarrée : les deux options de redémarrage doivent rester désactivées.</p><div class="admonition xdripitem"><p class="admonition-title">Continuer sans calibrations <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Toujours utiliser les données s&#39;il n&#39;y a pas assez de bonnes calibrations (expérimental!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Réduire le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser des heuristiques pour minimiser le scan Bluetooth + économie d&#39;énergie</p></div><div class="admonition xdripitem"><p class="admonition-title">Éviter le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Éviter de scanner autant que possible (réduit la consommation de la batterie)</p></div><div class="info custom-block"><p class="custom-block-title">Options de scan</p><p>Réduire le scan et Éviter le scan économisent la batterie mais sont désastreuses sur certains téléphones (Samsung, marques chinoises...). Commencez avec les deux désactivées : n&#39;essayez de les activer, une à la fois, qu&#39;une fois votre connexion fiable.</p></div><div class="admonition xdripitem"><p class="admonition-title">Permettre la dissociation OB1 <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Le collecteur OB1 peut démorcer si il pense que le chiffrement a échoué. Si vous avez des problèmes avec l&#39;association, désactivez cette option. Si vous perdez alors totalement la connexion, assurez-vous qu&#39;elle est activée.</p></div><div class="admonition xdripitem"><p class="admonition-title">Contournement de jumelage spécial <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Activez Contournement de jumelage spécial sur les téléphones Samsung et certains téléphones chinois.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/misc.html">Autres options diverses</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Mode développeur <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Permet de changer les paramètres les plus dangereux qui pourraient tout casser !</p></div><div class="admonition xdripitem"><p class="admonition-title">Invité pour l’optimisation de la batterie <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Sur Android 6+ s&#39;assurer que l&#39;optimisation de la batterie est désactivée (recommandé).</p></div><div class="admonition xdripitem"><p class="admonition-title">Solutions de contournement Wake <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utiliser des contournements pour éviter le comportement Android non standard de certains terminaux. Sans cela, les collecteurs ne peuvent pas obtenir les données.</p></div><div class="admonition xdripitem"><p class="admonition-title">Utilisation Wakelocks excessive <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Wakelocks anciennes qui peuvent drainer la batterie, mais pourraient être nécessaires pour NightWatch ou Android Wear</p></div><div class="admonition xdripitem"><p class="admonition-title">Afficher les valeurs prédictives <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Vieille méthode - non recommandée !</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrage du service agressif <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Redémarrer constamment le service de collecte en cas de soupçon de données manquantes. Activer uniquement si vous observez des pertes de données.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../calibrate/advancedcal.html">Calibration avancée</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration automatique <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrer en utilisant les nouvelles valeurs de glycémies si les conditions semblent pouvoir le faire, sans demander confirmation (expérimental)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/bluetooth.html">Paramètres Bluetooth</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Activer le Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Activer automatiquement bluetooth s&#39;il est éteint lorsqu&#39;on tente de se connecter à un périphérique bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Garde-fou Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Réinitialiser Bluetooth en le désactivant puis réactivant si nous n’obtenons rien pendant 20 minutes</p></div><div class="admonition xdripitem"><p class="admonition-title">Fermer GATT sur déconnexion BLE <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Si le garde-fou Bluetooth s&#39;active souvent alors vous pouvez essayer de décocher cette option pour voir si ça aide</p></div><div class="admonition xdripitem"><p class="admonition-title">Utiliser le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scanner avant de se connecter sur xBridge et Bluetooth Libre</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Faire confiance à Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser et faire confiance à la fonctionnalité de connexion auto Bluetooth d&#39;Android</p></div><p>Commencez avec Faire confiance à Auto-Connect désactivé. N&#39;essayez de l&#39;activer que si vous perdez sans cesse la connexion.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les scans en arrière-plan <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utiliser la fonction de scan en arrière-plan d&#39;Android 8+</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Wakelocks Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Anciens wakelocks Bluetooth qui peuvent drainer la batterie un peu plus, mais pourraient être nécessaire pour la réception bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Mode de sondage xBridge+ <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Support expérimental pour la fonction de sondage xBridge+</p></div><h4 id="starting-the-sensor" tabindex="-1">Démarrer le capteur <a class="header-anchor" href="#starting-the-sensor" aria-label="Permalink to &quot;Démarrer le capteur {#starting-the-sensor}&quot;">​</a></h4><p>Insérez le capteur en suivant les instructions de l&#39;applicateur du fabricant. La session démarre d&#39;elle-même dès l&#39;insertion du capteur : il n&#39;y a rien à démarrer (ni à arrêter) dans xDrip.</p><p>Notez le code d&#39;appairage à 4 chiffres indiqué sur l&#39;applicateur ; vous en aurez besoin ensuite. Si vous portez deux capteurs pendant un changement, marquez l&#39;ancien au stylo pour ne pas retirer le mauvais plus tard.</p><h4 id="connecting-xdrip-to-the-sensor" tabindex="-1">Connecter xDrip au capteur <a class="header-anchor" href="#connecting-xdrip-to-the-sensor" aria-label="Permalink to &quot;Connecter xDrip au capteur {#connecting-xdrip-to-the-sensor}&quot;">​</a></h4><ol><li>Dans Paramètres Android → Appareils connectés, oubliez les appareils nommés <code>DXCM**</code>, <code>DX01**</code>, <code>DX02**</code> ou <code>DX04**</code> (où <code>**</code> représente deux caractères quelconques), s&#39;il y en a.</li><li>Éloignez les capteurs déjà utilisés de plus de 10 mètres ou isolez-les (une boîte en métal fonctionne).</li><li>Saisissez le code d&#39;appairage à 4 chiffres de l&#39;applicateur :</li></ol><div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Paramètres<br>  ID de l&#39;émetteur Dexcom</p></div><p>Surveillez la <a href="./../troubleshoot/systemstatus.html">page Dex Status</a> et acceptez la demande d&#39;appairage lorsqu&#39;elle apparaît. Si le capteur a été inséré il y a plus de 30 minutes, vous devriez voir des valeurs immédiatement ; s&#39;il vient d&#39;être inséré, il apparaît en préchauffage et la page d&#39;état se remplit au fil du temps. Une fois les tensions de batterie affichées, vous pouvez réactiver votre pompe ou votre récepteur sans risque.</p><h4 id="grace-period" tabindex="-1">Période de grâce <a class="header-anchor" href="#grace-period" aria-label="Permalink to &quot;Période de grâce {#grace-period}&quot;">​</a></h4><p>Un G7/ONE+ fonctionne 10 jours plus une période de grâce de 12 heures, soit 10,5 jours au total. Utilisez ces 12 heures supplémentaires comme marge pour le changement, ou pour faire se chevaucher les capteurs (pré-trempage) : les premières heures d&#39;un nouveau G7 sont les moins stables, donc insérer le capteur suivant avant la fin de l&#39;ancien donne des valeurs plus régulières au moment du changement.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Démarrer un capteur suivant <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Démarrer un capteur suivant {#starting-a-subsequent-sensor}&quot;">​</a></h4><p>Passer à un nouveau capteur se résume à un changement de code :</p><ol><li>Insérez le nouveau capteur vers le 10e jour de l&#39;ancien (voir <a href="#starting-the-sensor">Démarrer le capteur</a>).</li><li>Au moment de basculer, saisissez le code d&#39;appairage à 4 chiffres du nouveau capteur comme <a href="#connecting-xdrip-to-the-sensor">ID de l&#39;émetteur</a> et acceptez la nouvelle demande d&#39;appairage.</li></ol><p>Deux astuces utiles :</p><ul><li>Si l&#39;ancien capteur apparaît encore comme appareil <code>DXCM**</code> dans l&#39;historique Bluetooth d&#39;Android, oubliez-le.</li><li>Désactivez la collecte dans xDrip <em>avant</em> de retirer l&#39;ancien capteur : sinon, il risque d&#39;enregistrer une dernière valeur très basse au moment où il quitte votre peau.</li></ul><div class="info custom-block"><p class="custom-block-title">Utilisateurs de pompe ou de récepteur</p><p>Désactivez d&#39;abord la connexion de la pompe ou du récepteur, laissez xDrip se connecter au nouveau capteur, puis réactivez la pompe une fois les valeurs stables. Si le capteur ne se connecte pas, attendez 15 minutes que le <a href="./../troubleshoot/g7.html#g7-rapid-reconnect-mode">mode de reconnexion rapide</a> s&#39;active.</p></div><h4 id="unknown-firmware" tabindex="-1">Firmware inconnu <a class="header-anchor" href="#unknown-firmware" aria-label="Permalink to &quot;Firmware inconnu {#unknown-firmware}&quot;">​</a></h4><p>Si la version du firmware est signalée comme inconnue sur la page <a href="./../troubleshoot/systemstatus.html">État du système</a>, votre xDrip est très probablement obsolète : mettez-le d&#39;abord à jour vers la dernière version. Si la version la plus récente la signale toujours, merci de le signaler dans les <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussions GitHub</a>.</p><h4 id="problems" tabindex="-1">Des problèmes ? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Des problèmes ? {#problems}&quot;">​</a></h4><p>Consultez la page <a href="./../troubleshoot/g7.html">Dépannage G7, ONE+</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',70)])])}const q=o(p,[["render",c]]);export{y as __pageData,q as default};
